import sys
import json

def convert(infile, outfile, max_count=10):
    out = {"data": []}
    count = 0
    with open(infile) as f:
        header = f.readline()  # skip header line
        for line in f:
            if count >= max_count:
                break
            entry = json.loads(line)
            o = {
                "context": entry["context"],
                "qas": []
            }
            for qa in entry.get("qas", []):
                qas_obj = {
                    "id": qa.get("id", ""),
                    "question": qa.get("question", ""),
                    "answers": [{"text": ans, "answer_start": qa.get("detected_answers", [{}])[0].get("char_spans", [[-1]])[0][0] if qa.get("detected_answers") else -1} for ans in qa.get("answers", [])]
                }
                o["qas"].append(qas_obj)
            out["data"].append(o)
            count += 1
    with open(outfile, "w") as outF:
        json.dump(out, outF)

if __name__ == "__main__":
    # Usage: python convert_mrqa_to_squad.py infile outfile
    infile, outfile = sys.argv[1], sys.argv[2]
    convert(infile, outfile, max_count=10)

